  Intent bi(){return registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));}
  int level(){Intent i=bi();return i==null?-1:i.getIntExtra(BatteryManager.EXTRA_LEVEL,-1);} float temp(){Intent i=bi();return i==null?0:i.getIntExtra(BatteryManager.EXTRA_TEMPERATURE,0)/10f;} int volt(){Intent i=bi();return i==null?0:i.getIntExtra(BatteryManager.EXTRA_VOLTAGE,0);} int status(){Intent i=bi();return i==null?0:i.getIntExtra(BatteryManager.EXTRA_STATUS,0);} long ua(){try{return((BatteryManager)getSystemService(BATTERY_SERVICE)).getLongProperty(BatteryManager.BATTERY_PROPERTY_CURRENT_NOW);}catch(Exception e){return 0;}}
  String charge(){return status()==BatteryManager.BATTERY_STATUS_CHARGING?"Laddar":status()==BatteryManager.BATTERY_STATUS_FULL?"Full":"Batteri";} String fmt(float x){return String.format(Locale.ROOT,"%.1f",x);} String tname(){float x=temp();return x>=43?"Mycket varm":x>=40?"Varm":x>=35?"Normal/varm":"Normal";}
  int ram(){ActivityManager a=(ActivityManager)getSystemService(ACTIVITY_SERVICE);ActivityManager.MemoryInfo m=new ActivityManager.MemoryInfo();a.getMemoryInfo(m);return(int)((m.totalMem-m.availMem)*100/m.totalMem);} long free(){return new StatFs(getFilesDir().getPath()).getAvailableBytes()/1073741824L;}
  int score(){int s=100;if(temp()>=43)s-=22;else if(temp()>=40)s-=12;if(ram()>92)s-=8;if(free()<20)s-=8;if(!shOk())s-=4;if(level()<15)s-=5;return Math.max(0,s);} int safe(){int n=0;for(String[]a:PK)if(a[2].equals("Säker")&&installed(a[1])&&enabled(a[1]))n++;return n;}

  void sampleBaseline(){long now=System.currentTimeMillis(),last=p.getLong("baseline_time",0);if(now-last<30*60*1000)return;float oldT=p.getFloat("base_temp",temp()),oldR=p.getFloat("base_ram",ram());p.edit().putFloat("base_temp",oldT*.85f+temp()*.15f).putFloat("base_ram",oldR*.85f+ram()*.15f).putLong("baseline_time",now).apply();}
  void advisor(){base("🧠 SMART ADVISOR 4.0","Jämför nuläget med telefonens lokala baslinje",true);float bt=p.getFloat("base_temp",temp()),br=p.getFloat("base_ram",ram());note("Nu: "+fmt(temp())+"°C • RAM "+ram()+"% • "+free()+" GB ledigt\nBaslinje: "+fmt(bt)+"°C • RAM "+fmt(br)+"%");sec("Rekommendationer");int n=0;if(temp()>bt+4||temp()>=40)note(++n+". 🔥 Varmare än normalt. Vänta med benchmark/gaming.");if(ram()>br+18)note(++n+". 🧠 RAM ligger tydligt över din normala nivå. Android får först hantera minnet själv.");if(free()<20)note(++n+". 💾 Frigör lagring före större uppdateringar.");if(!shOk())note(++n+". 🔧 Starta Shizuku för Debloat-funktionerna.");if(safe()>0)note(++n+". 🛡️ "+safe()+" säkra paket kan granskas i Debloat.");if(n==0)note("✅ Inga viktiga åtgärder just nu.");btn("Öppna Debloat 7.0",()->debloat());log("Advisor 4.0: Health "+score());}

  void debloat(){base("🛡️ SMART DEBLOAT 7.0","Samsung • Google • Meta • risk • Recovery",true);note(shStatus());btn("✨ Rekommenderad säker batch",()->recommended());String last="";for(String[]a:PK)if(installed(a[1])){if(!a[3].equals(last)){sec(a[3]);last=a[3];}TextView z=text(a[0]+" • "+a[2],18,true);z.setTextColor(a[2].equals("Försiktig")?AMBER:GREEN);root.addView(z);note(a[4]+"\n"+a[1]+"\nStatus: "+(enabled(a[1])?"✅ Aktiv":"⛔ Avaktiverad"));if(enabled(a[1]))btn("Avaktivera "+a[0],()->ask(a));else btn("Återställ "+a[0],()->shell("pm enable --user 0 "+a[1],a[1],false));}sec("Skydd");note("Systemkritiska paket finns inte i rekommenderad batch. Varje ändring loggas och kan återställas.");}
  void recommended(){ArrayList<String[]> l=new ArrayList<>();for(String[]a:PK)if(a[2].equals("Säker")&&installed(a[1])&&enabled(a[1]))l.add(a);if(l.isEmpty()){toast("Inga säkra aktiva förslag");return;}StringBuilder s=new StringBuilder("Snapshot skapas först.\n\n");for(String[]a:l)s.append("• ").append(a[0]).append("\n");new AlertDialog.Builder(this).setTitle("Granska batch").setMessage(s).setNegativeButton("Avbryt",null).setPositiveButton("Avaktivera "+l.size(),(d,w)->{snapshot();for(String[]a:l)shell("pm disable-user --user 0 "+a[1],a[1],true);}).show();}
  void ask(String[]a){String warn=a[2].equals("Försiktig")?"\n\n⚠️ Den här appen kan påverka en funktion du använder.":"";new AlertDialog.Builder(this).setTitle("Avaktivera "+a[0]+"?").setMessage(a[4]+"\nRisk: "+a[2]+warn+"\n\nRecovery Center kan återställa.").setNegativeButton("Avbryt",null).setPositiveButton("Avaktivera",(d,w)->{snapshot();shell("pm disable-user --user 0 "+a[1],a[1],true);}).show();}

  void apps(){base("📦 APP MANAGER 2.0","Sök • system • användare • Samsung • Google • avaktiverade",true);EditText e=new EditText(this);e.setHint("Sök app eller paket…");e.setTextColor(Color.WHITE);e.setHintTextColor(Color.GRAY);root.addView(e);btn("Alla",()->appList(e.getText().toString(),0));btn("Systemappar",()->appList(e.getText().toString(),1));btn("Användarappar",()->appList(e.getText().toString(),2));btn("Avaktiverade",()->appList(e.getText().toString(),3));btn("Samsung",()->appList(e.getText().toString(),4));btn("Google",()->appList(e.getText().toString(),5));}
  void appList(String q,int f){PackageManager pm=getPackageManager();ArrayList<ApplicationInfo>m=new ArrayList<>();String z=q.toLowerCase(Locale.ROOT);for(ApplicationInfo a:pm.getInstalledApplications(0)){boolean sy=(a.flags&ApplicationInfo.FLAG_SYSTEM)!=0;String n=""+pm.getApplicationLabel(a);if(f==1&&!sy||f==2&&sy||f==3&&a.enabled)continue;if(f==4&&!a.packageName.startsWith("com.samsung")&&!a.packageName.startsWith("com.sec"))continue;if(f==5&&!a.packageName.startsWith("com.google"))continue;if(z.isEmpty()||n.toLowerCase().contains(z)||a.packageName.toLowerCase().contains(z))m.add(a);}m.sort((a,b)->(""+pm.getApplicationLabel(a)).compareToIgnoreCase(""+pm.getApplicationLabel(b)));int n=Math.min(250,m.size());String[]x=new String[n];for(int i=0;i<n;i++)x[i]=pm.getApplicationLabel(m.get(i))+"\n"+m.get(i).packageName+(m.get(i).enabled?" • Aktiv":" • Avaktiverad");new AlertDialog.Builder(this).setTitle("Matchningar: "+m.size()).setItems(x,(d,i)->inspect(m.get(i).packageName)).setNegativeButton("Stäng",null).show();}
  void inspect(String x){try{PackageManager pm=getPackageManager();ApplicationInfo a=pm.getApplicationInfo(x,0);PackageInfo pi=pm.getPackageInfo(x,0);boolean sy=(a.flags&ApplicationInfo.FLAG_SYSTEM)!=0;new AlertDialog.Builder(this).setTitle(""+pm.getApplicationLabel(a)).setMessage("Paket: "+x+"\nVersion: "+pi.versionName+"\nTyp: "+(sy?"Systemapp":"Användarapp")+"\nStatus: "+(a.enabled?"Aktiv":"Avaktiverad")+"\nSenast uppdaterad: "+new SimpleDateFormat("yyyy-MM-dd",Locale.getDefault()).format(new Date(pi.lastUpdateTime))).setNeutralButton("Appinfo",(d,w)->startActivity(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+x)))).setNegativeButton("Kopiera ID",(d,w)->{((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("pkg",x));toast("Kopierat");}).setPositiveButton("OK",null).show();}catch(Exception e){toast("Paketet hittades inte");}}

  void thermal(){base("🌡️ THERMAL WATCH 4.0","Trend • min • max • medel • historik",true);float[]s=stats("temps");note("Aktuellt: "+fmt(temp())+"°C • "+tname());if(s[3]>0)note("Min "+fmt(s[0])+"°C • Max "+fmt(s[1])+"°C • Medel "+fmt(s[2])+"°C • "+(int)s[3]+" mätningar\nTrend: "+trend());btn("Starta 1 minut",()->startTemp(12));btn("Starta 5 minuter",()->startTemp(60));btn("Starta 15 minuter",()->startTemp(180));btn("Starta 30 minuter",()->startTemp(360));sec("Senaste 20");note(latest("temps",20));btn("Rensa temperaturhistorik",()->{p.edit().remove("temps").apply();thermal();});}
  void startTemp(int n){stop();final int[]c={0};watch=new Runnable(){public void run(){save("temps",temp(),720);if(++c[0]<n)h.postDelayed(this,5000);else{watch=null;toast("Thermal Watch klar");thermal();}}};h.post(watch);}
  void stop(){if(watch!=null){h.removeCallbacks(watch);watch=null;}}
  void save(String k,float v,int max){String now=new SimpleDateFormat("MM-dd HH:mm:ss",Locale.getDefault()).format(new Date()),old=p.getString(k,""),all=now+" • "+v+(old.isEmpty()?"":"\n"+old);String[]a=all.split("\n");StringBuilder b=new StringBuilder();for(int i=0;i<Math.min(max,a.length);i++){if(i>0)b.append("\n");b.append(a[i]);}p.edit().putString(k,b.toString()).apply();}
  float[]stats(String k){float mi=999,ma=-999,sum=0;int n=0;for(String l:p.getString(k,"").split("\n"))try{float x=Float.parseFloat(l.substring(l.lastIndexOf("•")+1).trim());mi=Math.min(mi,x);ma=Math.max(ma,x);sum+=x;n++;}catch(Exception e){}return n==0?new float[]{0,0,0,0}:new float[]{mi,ma,sum/n,n};}
  String latest(String k,int n){String[]a=p.getString(k,"Ingen historik").split("\n");StringBuilder b=new StringBuilder();for(int i=0;i<Math.min(n,a.length);i++)b.append(a[i]).append("\n");return b.toString().trim();}
  String trend(){String[]a=p.getString("temps","").split("\n");if(a.length<4)return"För lite data";try{float x=Float.parseFloat(a[0].substring(a[0].lastIndexOf("•")+1).trim()),y=Float.parseFloat(a[Math.min(a.length-1,11)].substring(a[Math.min(a.length-1,11)].lastIndexOf("•")+1).trim()),d=x-y;return d>.7?"Stigande +"+fmt(d)+"°C":d<-.7?"Sjunkande "+fmt(d)+"°C":"Stabil";}catch(Exception e){return"Okänd";}}

  void battery(){base("⚡ CHARGING TEST PRO","Sensorbaserad ström/effekt • temperatur • sparade serier",true);long u=ua();double v=volt()/1000.0,w=v*Math.abs(u)/1000000.0;String cur=Math.abs(u)<1000?"Ingen mätbar ström just nu":String.format(Locale.ROOT,"%.0f mA",u/1000.0);note("Batteri: "+level()+"%\nTemperatur: "+fmt(temp())+"°C\nSpänning: "+String.format(Locale.ROOT,"%.3f",v)+" V\nStröm: "+cur+"\nUppskattad effekt: "+String.format(Locale.ROOT,"%.2f",w)+" W\nStatus: "+charge());float[]s=stats("watts");if(s[3]>0)note("Senaste serie • Min "+fmt(s[0])+" W • Max "+fmt(s[1])+" W • Medel "+fmt(s[2])+" W");note("Effekten är en Android-sensoruppskattning, inte laddarens märkta watt.");btn("Starta 1 min",()->startPower(12));btn("Starta 5 min",()->startPower(60));btn("Starta 10 min",()->startPower(120));btn("Rensa laddningsserie",()->{p.edit().remove("watts").apply();battery();});}
  void startPower(int n){stop();p.edit().remove("watts").apply();final int[]c={0};watch=new Runnable(){public void run(){float w=(float)(volt()/1000.0*Math.abs(ua())/1000000.0);save("watts",w,240);save("chargeTemps",temp(),240);if(++c[0]<n)h.postDelayed(this,5000);else{watch=null;float[]s=stats("watts"),t=stats("chargeTemps");String out="Effekt "+fmt(s[0])+" / "+fmt(s[2])+" / "+fmt(s[1])+" W • Temp max "+fmt(t[1])+"°C";p.edit().putString("last_charge_test",out).apply();log("Laddningsprov: "+out);toast("Laddningsprov klart");battery();}}};h.post(watch);}

  void profiles(){base("🚗 GPS / JOBBLÄGE","Profiler som kan återställas",true);note("Aktiv profil: "+p.getString("profile","Standard"));btn("Balanserad",()->profile("Balanserad",60000,true,true,false));btn("Batteri",()->profile("Batteri",30000,true,false,false));btn("Gaming",()->profile("Gaming",120000,false,true,false));btn("Bil/GPS",()->profile("Bil/GPS",600000,true,true,true));btn("DeX",()->profile("DeX",600000,true,true,false));btn("Återställ tidigare läge",()->restoreProfile());}
  void remember(){if(p.contains("pre_timeout"))return;try{p.edit().putInt("pre_timeout",Settings.System.getInt(getContentResolver(),Settings.System.SCREEN_OFF_TIMEOUT,60000)).putInt("pre_bright",Settings.System.getInt(getContentResolver(),Settings.System.SCREEN_BRIGHTNESS_MODE,1)).putInt("pre_rotate",Settings.System.getInt(getContentResolver(),Settings.System.ACCELEROMETER_ROTATION,1)).apply();}catch(Exception e){}}
  void profile(String n,int t,boolean a,boolean o,boolean keep){if(!writeOk())return;remember();try{Settings.System.putInt(getContentResolver(),Settings.System.SCREEN_OFF_TIMEOUT,t);Settings.System.putInt(getContentResolver(),Settings.System.SCREEN_BRIGHTNESS_MODE,a?1:0);Settings.System.putInt(getContentResolver(),Settings.System.ACCELEROMETER_ROTATION,o?1:0);if(keep)getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);else getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);p.edit().putString("profile",n).apply();log("Profil aktiverad: "+n);toast(n+" aktiverad");}catch(Exception e){toast("Kunde inte ändra allt");}}
  void restoreProfile(){if(!writeOk())return;if(!p.contains("pre_timeout")){toast("Ingen sparad profilbas");return;}try{Settings.System.putInt(getContentResolver(),Settings.System.SCREEN_OFF_TIMEOUT,p.getInt("pre_timeout",60000));Settings.System.putInt(getContentResolver(),Settings.System.SCREEN_BRIGHTNESS_MODE,p.getInt("pre_bright",1));Settings.System.putInt(getContentResolver(),Settings.System.ACCELEROMETER_ROTATION,p.getInt("pre_rotate",1));p.edit().remove("pre_timeout").remove("pre_bright").remove("pre_rotate").putString("profile","Standard").apply();getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);log("Profil återställd");toast("Återställt");}catch(Exception e){toast("Misslyckades");}}

  void dex(){base("🖥️ DEX CENTER 2.0","Extern skärm • temperatur • laddning • snabbval",true);android.hardware.display.DisplayManager d=(android.hardware.display.DisplayManager)getSystemService(DISPLAY_SERVICE);int n=d==null?1:d.getDisplays().length;note((n>1?"✅ Extern skärm upptäckt":"Ingen extern skärm upptäckt")+"\nTemperatur "+fmt(temp())+"°C • Batteri "+level()+"% • "+charge()+" • RAM "+ram()+"%");btn("Aktivera DeX-profil",()->profile("DeX",600000,true,true,false));btn("Återställ profil",()->restoreProfile());btn("Skärminställningar",()->open(Settings.ACTION_DISPLAY_SETTINGS));btn("Ljudinställningar",()->open(Settings.ACTION_SOUND_SETTINGS));}

