  void snapshot(){Set<String>s=new HashSet<>();for(String[]a:PK)if(installed(a[1])&&enabled(a[1]))s.add(a[1]);p.edit().putStringSet("snapshot",s).putLong("snapshot_time",System.currentTimeMillis()).apply();log("Snapshot skapad");}
  void undo(){String x=p.getString("last_pkg","");if(x.isEmpty()){toast("Ingen ändring att ångra");return;}boolean d=p.getBoolean("last_disabled",false);shell((d?"pm enable --user 0 ":"pm disable-user --user 0 ")+x,x,!d);}
